// go: github.com/microsoft/TypeScript/tsc/internal/ls.displayPartsWriter.addRun f82db4d1
fun com.xemantic.typescript.tsgo.ls.displayPartsWriter?.addRun(classification: ClassificationTypeName, text: String) {
    if (text == "") {
        return
    }
    if (this!!.vsCapability) {
        this!!.runs = this!!.runs.append1(VSClassifiedTextRun(classificationTypeName = classification.value, text = text))
    }
    this!!.lastWritten = text
    this!!.builder.writeString(text)
}

// go: github.com/microsoft/TypeScript/tsc/internal/ls.displayPartsWriter.WriteClassified 6df857be
fun com.xemantic.typescript.tsgo.ls.displayPartsWriter?.writeClassified(text: String, classification: ClassificationTypeName) {
    this.addRun(classification, text)
}

// go: github.com/microsoft/TypeScript/tsc/internal/ls.displayPartsWriter.WriteFrom a34f124b
fun com.xemantic.typescript.tsgo.ls.displayPartsWriter?.writeFrom(other: com.xemantic.typescript.tsgo.ls.displayPartsWriter?) {
    this!!.builder.writeString(other!!.string())
    if (this!!.vsCapability) {
        this!!.runs = this!!.runs.appendSlice(other.getRuns())
    }
    if (other!!.lastWritten != "") {
        this!!.lastWritten = other!!.lastWritten
    }
}

